def create_policy_statement(policy):
    """Generate CREATE POLICY SQL statement from policy data"""
    schemaname = policy['schemaname']
    tablename = policy['tablename']
    policyname = policy['policyname']
    permissive = policy['permissive']
    roles = policy['roles']
    cmd = policy['cmd']
    qual = policy.get('qual')
    with_check = policy.get('with_check')
    
    # Build the CREATE POLICY statement
    stmt_parts = []
    stmt_parts.append(f"CREATE POLICY \"{policyname}\" ON {schemaname}.{tablename}")
    
    # Add FOR clause
    if cmd == 'ALL':
        stmt_parts.append("FOR ALL")
    else:
        stmt_parts.append(f"FOR {cmd}")
    
    # Add TO clause (roles)
    # roles is like "{authenticated}" or "{public}" or array
    if roles:
        # Parse roles array format - remove curly braces and split
        roles_clean = roles.strip('{}')
        if ',' in roles_clean:
            role_list = [r.strip().strip('"') for r in roles_clean.split(',')]
            stmt_parts.append(f"TO {', '.join(role_list)}")
        else:
            stmt_parts.append(f"TO {roles_clean.strip('\"')}")
    
    # Add USING clause (qual) - this is the USING expression
    if qual:
        stmt_parts.append(f"USING ({qual})")
    
    # Add WITH CHECK clause
    if with_check:
        stmt_parts.append(f"WITH CHECK ({with_check})")
    
    # PERMISSIVE is default, RESTRICTIVE would need to be specified
    # But CREATE POLICY doesn't have a PERMISSIVE keyword in standard SQL
    # So we don't include it
    
    return '\n'.join(stmt_parts) + ';'

def sanitize_filename(name):
    """Convert policy name to safe filename"""
    # Replace spaces and special characters with underscores
    # Keep it readable but filesystem-safe
    name = re.sub(r'[^\w\s-]', '', name)
    name = re.sub(r'[-\s]+', '_', name)
    return name

