try:
    # Parse the policies JSON
    policies_data = json.loads(policies_json)
    
    # Group policies by table for organization
    policies_by_table = {}
    for policy in policies_data:
        table = policy['tablename']
        if table not in policies_by_table:
            policies_by_table[table] = []
        policies_by_table[table].append(policy)
    
    # Write policies to individual files
    policy_count = 0
    for table, table_policies in sorted(policies_by_table.items()):
        for policy in table_policies:
            policy_name = policy['policyname']
            filename = f"{table}_{sanitize_filename(policy_name)}.sql"
            filepath = os.path.join(policies_dir, filename)
            
            policy_stmt = create_policy_statement(policy)
            
            with open(filepath, 'w', encoding='utf-8') as f:
                f.write(policy_stmt + '\n')
            
            policy_count += 1
    
    print(f"Successfully exported {policy_count} policies to {policies_dir}/")
    print(f"Policies organized by {len(policies_by_table)} tables")
    
except json.JSONDecodeError as e:
    print(f"Error parsing JSON: {e}")
    print("Please check the policies_json variable contains valid JSON")
except Exception as e:
    print(f"Error: {e}")
    import traceback
    traceback.print_exc()
